-- Verified source annotations; ORPHA IDs correspond to directly matched disease concepts.
on conflict (disease_id) do update set orpha_label=excluded.orpha_label,source_release=excluded.source_release;
on conflict (disease_id,hpo_id) do update set frequency_raw=excluded.frequency_raw,hpo_label_en=excluded.hpo_label_en;
on conflict (disease_id,gene_symbol,association_type) do nothing;
on conflict (disease_id,inheritance_name) do nothing;
on conflict (disease_id,onset_name) do nothing;
